import sys,json
from pathlib import Path
b=Path(__file__).resolve().parent;sys.path.insert(0,str(b));from persistent_sql import Client
p=b/'out/native/ashlar_scoped_maintenance_preflight_r299';assert not p.exists();c=Client(p,observation_timeout=120,cancel_after=60);s=json.loads((b/'out/scoped-maintenance-selection-r298.json').read_text());t=s['candidate_existing_table'];sid='01f1c24d-a34f-1227-a00f-886835ac10b6';old=c.w.api_client.do('GET','/api/2.0/sql/statements/'+sid);assert old['status']['state']=='CANCELED'
rows=c.sql('detail','DESCRIBE DETAIL '+t);cols=[x['name'] for x in c.records[-1]['response']['manifest']['schema']['columns']];d=dict(zip(cols,rows[0]));assert d['id']==s['expected_candidate_uuid'];assert json.loads(d['clusteringColumns'])==['lookup_hash']
h=c.sql('history','DESCRIBE HISTORY '+t+' LIMIT 20');cols=[x['name'] for x in c.records[-1]['response']['manifest']['schema']['columns']];history=[dict(zip(cols,r)) for r in h];assert int(history[0]['version'])==2 and not any(x['operation']=='OPTIMIZE' for x in history)
f=c.sql('ranges',f'SELECT _metadata.file_path,max(_metadata.file_size),count(*),min(lookup_hash),max(lookup_hash) FROM {t} VERSION AS OF 2 GROUP BY _metadata.file_path');assert sum(int(r[2]) for r in f)==39990000;hi='1'+'0'*63;selected=[r for r in f if r[3]<hi];size=sum(int(r[1]) for r in selected);assert size<=2500000000
native=c.history();result={'state':'Existing candidate passes scoped maintenance preflight','detail':d,'history':history,'files':f,'overlapping_files':len(selected),'overlapping_bytes':size,'canceled_prior_statement':{'statement_id':sid,'state':old['status']['state']},'qualification':'Read-only UUID/head/history and observed file range preflight. No maintenance executed; file range inclusion is not stored Delta statistics or runtime admission.'};(p/'summary.json').write_text(json.dumps(result,indent=2)+'\n');(p/'live-statement.json').unlink();print(result['state'],len(selected),size)
